message.content:
{
  "summary": "Your medication review has identified three safety concerns regarding your current prescriptions and recent lab results. Please review these points and consult your healthcare provider.",
  "explanations": [
    {
      "finding_id": "DEMO-INT-002",
      "plain_language": "Tritace and Aldactone can both increase your blood potassium levels. Because you have chronic kidney disease, your body may have more difficulty clearing potassium, which increases the risk of levels becoming too high. Please discuss this combination with your doctor or pharmacist."
    },
    {
      "finding_id": "DEMO-LAB-001:glucophage",
      "plain_language": "Your recent lab results show your kidney function is below the level where Glucophage is typically recommended, due to a risk of a condition called lactic acidosis. Please contact your doctor or pharmacist promptly to discuss this."
    },
    {
      "finding_id": "DEMO-LAB-002:aldactone",
      "plain_language": "Aldactone can raise your blood potassium levels. Your recent lab results show your potassium is already above the normal range. Please contact your doctor or pharmacist promptly to discuss this finding."
    }
  ]
}
